INSERT INTO `doctor_notes` VALUES (1,'','0000-00-00 00:00:00','2025-04-13 14:37:57'),(2,'Theo dõi huyết áp hàng ngày, tái khám sau 1 tháng.','0000-00-00 00:00:00','0000-00-00 00:00:00'),(3,'Kiểm soát đường huyết, ăn kiêng, tập thể dục.','0000-00-00 00:00:00','0000-00-00 00:00:00'),(4,'Giữ ấm cơ thể, tránh khói bụi, tái khám nếu ho kéo dài.','0000-00-00 00:00:00','0000-00-00 00:00:00'),(5,'Ăn chín uống sôi, tránh đồ ăn khó tiêu.','0000-00-00 00:00:00','0000-00-00 00:00:00'),(6,'Uống thuốc đúng giờ, kiêng chua cay, tái khám sau 2 tuần.','0000-00-00 00:00:00','0000-00-00 00:00:00'),(7,'Vệ sinh mũi họng, nghỉ ngơi tại nhà.','0000-00-00 00:00:00','0000-00-00 00:00:00'),(8,'Giữ vệ sinh da, tránh tiếp xúc dị nguyên, bôi thuốc theo chỉ định.','0000-00-00 00:00:00','0000-00-00 00:00:00'),(10,'Bổ sung dinh dưỡng, nghỉ ngơi hợp lý, tránh căng thẳng.','0000-00-00 00:00:00','0000-00-00 00:00:00'),(11,'Uống thuốc đúng giờ, theo toa','2025-07-25 15:30:21','2025-07-25 15:30:21');
