--
-- Table structure for table `examination_medications`
--

DROP TABLE IF EXISTS `examination_medications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `examination_medications` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `examination_id` bigint NOT NULL,
  `medication_id` bigint DEFAULT NULL,
  `morning` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `afternoon` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `unit` varchar(15) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `days_of_use` int DEFAULT NULL,
  `total_quantity_med` int DEFAULT NULL,
  `note` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `examination_id` (`examination_id`),
  KEY `medication_id` (`medication_id`),
  CONSTRAINT `examination_medications_ibfk_1` FOREIGN KEY (`examination_id`) REFERENCES `examinations` (`id`) ON DELETE CASCADE,
  CONSTRAINT `examination_medications_ibfk_2` FOREIGN KEY (`medication_id`) REFERENCES `medications` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1255 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

