--
-- Table structure for table `examinations`
--

DROP TABLE IF EXISTS `examinations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `examinations` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `patient_id` bigint NOT NULL,
  `reason` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `diagnosis_id` int NOT NULL,
  `doctor_note_id` int NOT NULL,
  `note` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `pulse` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `blood_pressure` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `respiratory_rate` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `weight` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `height` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `temperature` varchar(50) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `type` enum('chỉ định','toa thuốc') COLLATE utf8mb4_general_ci NOT NULL,
  `follow_up` varchar(15) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `price` int DEFAULT NULL,
  `state` varchar(10) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `patient_id` (`patient_id`),
  KEY `examinations_ibfk_2` (`diagnosis_id`),
  KEY `examinations_ibfk_3` (`doctor_note_id`),
  CONSTRAINT `examinations_ibfk_1` FOREIGN KEY (`patient_id`) REFERENCES `patients` (`id`) ON DELETE CASCADE,
  CONSTRAINT `examinations_ibfk_2` FOREIGN KEY (`diagnosis_id`) REFERENCES `diagnoses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `examinations_ibfk_3` FOREIGN KEY (`doctor_note_id`) REFERENCES `doctor_notes` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1081 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `examinations`
